/* Banco · Escenario 1 — Customer Support Resolution Agent (D1 14 · D2 9 · D5 9) */
(function () {
  const o = (en, es, ok, wen, wes) => ({ t: { en, es }, ok: !!ok, w: { en: wen, es: wes } });
  const Q = (id, d, ts, lv, pat, en, es, opts, extra = {}) => Object.assign({ id, s: 1, d, ts, lv, pat, q: { en, es }, o: opts }, extra);

  CAF.addBank([
    /* ---------------- D1 ---------------- */
    Q('s1q01', 1, '1.4', 'mid', 'deterministic',
      'Production data shows that in 12% of cases, your agent skips get_customer entirely and calls lookup_order using only the customer\'s stated name, occasionally leading to misidentified accounts and incorrect refunds. What change would most effectively address this reliability issue?',
      'Los datos de producción muestran que en el 12 % de los casos tu agente se salta get_customer por completo y llama a lookup_order usando solo el nombre que dice el cliente, lo que a veces provoca cuentas mal identificadas y reembolsos incorrectos. ¿Qué cambio resolvería este problema de fiabilidad de forma más eficaz?',
      [o('Add a programmatic prerequisite that blocks lookup_order and process_refund calls until get_customer has returned a verified customer ID.', 'Añadir un prerrequisito programático que bloquee las llamadas a lookup_order y process_refund hasta que get_customer haya devuelto un ID de cliente verificado.', 1,
         'Correct. Critical ordering with financial consequences needs deterministic enforcement.', 'Correcta. Un orden crítico con consecuencias financieras necesita enforcement determinista.'),
       o('Enhance the system prompt to state that customer verification via get_customer is mandatory before any order operations.', 'Reforzar el system prompt indicando que verificar al cliente con get_customer es obligatorio antes de cualquier operación con pedidos.', 0,
         'Still probabilistic compliance; insufficient when errors cost money.', 'Sigue siendo cumplimiento probabilístico; no basta cuando los errores cuestan dinero.'),
       o('Add few-shot examples showing the agent always calling get_customer first, even when customers volunteer order details.', 'Añadir ejemplos few-shot donde el agente siempre llama primero a get_customer, incluso cuando el cliente da los datos del pedido.', 0,
         'Lowers the rate but cannot guarantee it; still probabilistic.', 'Baja la tasa, pero no la garantiza; sigue siendo probabilístico.'),
       o('Implement a routing classifier that analyzes each request and enables only the subset of tools appropriate for that request type.', 'Implementar un clasificador de enrutado que analice cada petición y active solo las tools adecuadas para ese tipo de petición.', 0,
         'Addresses tool availability, not tool ordering, which is the actual problem.', 'Ataca la disponibilidad de tools, no su orden, que es el problema real.')],
      { official: true }),

    Q('s1q02', 1, '1.1', 'basic', 'documented',
      'Your support agent sometimes replies "One moment, let me pull up your account…" and the conversation ends there. The loop code breaks as soon as a response contains a text block. What should the loop use to decide whether to continue?',
      'Tu agente de soporte a veces responde «Un momento, déjame consultar tu cuenta…» y la conversación termina ahí. El código del bucle sale en cuanto una respuesta contiene un bloque de texto. ¿Qué debería usar el bucle para decidir si continúa?',
      [o('Continue while stop_reason is "tool_use"; stop when it is "end_turn".', 'Continuar mientras stop_reason sea "tool_use"; parar cuando sea "end_turn".', 1, 'stop_reason is the documented control signal.', 'stop_reason es la señal de control documentada.'),
       o('Stop when the assistant text contains a closing phrase such as "anything else I can help with?"', 'Parar cuando el texto del asistente contenga una frase de cierre como «¿algo más en lo que pueda ayudar?»', 0, 'Parsing natural language is an anti-pattern.', 'Interpretar lenguaje natural es un anti-patrón.'),
       o('Stop after a fixed number of iterations, e.g. 3.', 'Parar tras un número fijo de iteraciones, p. ej. 3.', 0, 'An iteration cap should only be a safety net.', 'Un tope de iteraciones solo debe ser una red de seguridad.'),
       o('Stop whenever the previous turn produced no tool_result, since that means no work is pending', 'Parar cuando el turno anterior no produjo ningún tool_result, ya que eso significa que no queda trabajo pendiente', 0, 'Unrelated to whether the model wants more tools now.', 'No indica si el modelo quiere más tools ahora.')]),

    Q('s1q03', 1, '1.1', 'mid', 'documented',
      'A long refund explanation is cut off mid-sentence and the loop treats it as the final answer. Logs show stop_reason: "max_tokens". What is the right interpretation?',
      'Una explicación larga de un reembolso se corta a mitad de frase y el bucle la trata como respuesta final. Los logs muestran stop_reason: "max_tokens". ¿Cuál es la interpretación correcta?',
      [o('The output hit the token limit; it is not a completion signal, so raise max_tokens or continue the turn.', 'La salida llegó al límite de tokens; no es una señal de finalización, así que sube max_tokens o continúa el turno.', 1, '"max_tokens" means truncated, not finished.', '"max_tokens" significa truncado, no terminado.'),
       o('The model finished normally: max_tokens is just another end_turn variant, so show the answer as final.', 'El modelo terminó con normalidad: max_tokens es solo otra variante de end_turn, así que muestra la respuesta como final.', 0, 'Only end_turn means the model finished.', 'Solo end_turn significa que el modelo terminó.'),
       o('The model wants a tool to be executed.', 'El modelo quiere que se ejecute una tool.', 0, 'That would be stop_reason "tool_use".', 'Eso sería stop_reason "tool_use".'),
       o('The conversation history is now too long, so the oldest turns must be deleted before the next request.', 'El historial ya es demasiado largo, así que hay que borrar los turnos más antiguos antes de la siguiente petición.', 0, 'max_tokens limits output length, not input.', 'max_tokens limita la longitud de la salida, no de la entrada.')]),

    Q('s1q04', 1, '1.1', 'basic', 'rootcause',
      'After looking up order #48121, the agent asks the customer for the order number again two turns later. The loop executes tools and prints their results to the log, then calls the API with the previous messages. Most likely cause?',
      'Tras consultar el pedido #48121, el agente vuelve a pedir el número de pedido dos turnos después. El bucle ejecuta las tools, imprime sus resultados en el log y llama a la API con los mensajes anteriores. ¿Causa más probable?',
      [o('Tool results are not appended to the conversation as tool_result blocks, so the model never sees them.', 'Los resultados de las tools no se añaden a la conversación como bloques tool_result, así que el modelo nunca los ve.', 1, 'The API is stateless; results must be in messages.', 'La API no guarda estado; los resultados deben estar en los mensajes.'),
       o('The model\'s context window is too small to keep a full order record across several conversation turns.', 'La ventana de contexto del modelo es demasiado pequeña para conservar un pedido completo durante varios turnos.', 0, 'One order is tiny; the data was never sent.', 'Un pedido ocupa muy poco; el dato nunca se envió.'),
       o('The temperature is too high.', 'La temperatura es demasiado alta.', 0, 'Not a cause of missing information.', 'No causa que falte información.'),
       o('lookup_order needs a richer description so the model knows it should reuse earlier lookup results.', 'lookup_order necesita una descripción más rica para que el modelo sepa que debe reutilizar las consultas anteriores.', 0, 'The tool was selected and ran correctly.', 'La tool se eligió y se ejecutó bien.')]),

    Q('s1q05', 1, '1.4', 'mid', 'rootcause',
      'A customer writes: "My blender arrived cracked, and I was also charged twice for it." The agent fixes the replacement and ignores the double charge. Which design best handles messages like this?',
      'Un cliente escribe: «Mi licuadora llegó rota y además me la cobraron dos veces.» El agente gestiona la reposición e ignora el cobro doble. ¿Qué diseño maneja mejor mensajes así?',
      [o('Decompose the request into distinct issues, investigate each using shared context (verified customer), then give one unified resolution.', 'Descomponer la petición en temas distintos, investigar cada uno con el contexto compartido (cliente verificado) y dar una única resolución unificada.', 1, 'Documented multi-concern pattern.', 'Es el patrón documentado para peticiones con varios temas.'),
       o('Ask the customer to open a separate ticket for each issue so every case keeps its own clean history.', 'Pedir al cliente que abra un ticket por cada tema para que cada caso conserve su propio historial limpio.', 0, 'Shifts work to the customer and hurts first-contact resolution.', 'Traslada el trabajo al cliente y empeora la resolución en el primer contacto.'),
       o('Always escalate messages that contain more than one issue to a human agent, since combined requests carry a higher risk of mistakes.', 'Escalar siempre a un agente humano los mensajes con más de un tema, ya que las peticiones combinadas tienen más riesgo de error.', 0, 'Complexity alone is not an escalation trigger.', 'La complejidad por sí sola no es motivo de escalado.'),
       o('Handle only the issue mentioned first.', 'Atender solo el primer tema mencionado.', 0, 'That is the current failure.', 'Ese es justamente el fallo actual.')]),

    Q('s1q06', 1, '1.4', 'basic', 'rootcause',
      'Human agents receiving escalations complain they must re-interview every customer. What should the escalate_to_human payload contain?',
      'Los agentes humanos que reciben escalaciones se quejan de que tienen que volver a entrevistar a cada cliente. ¿Qué debe contener el payload de escalate_to_human?',
      [o('A structured handoff: customer ID, root cause, amounts, actions already taken, and the recommended next action.', 'Un traspaso estructurado: ID de cliente, causa raíz, importes, acciones ya realizadas y la siguiente acción recomendada.', 1, 'Humans lack the transcript; the summary must stand alone.', 'Las personas no tienen la conversación; el resumen debe valerse por sí mismo.'),
       o('A priority flag plus the customer\'s last message, so the human can jump straight into the conversation.', 'Un indicador de prioridad más el último mensaje del cliente, para que la persona entre directamente a la conversación.', 0, 'Not enough to act on.', 'No basta para actuar.'),
       o('The raw tool logs from the session.', 'Los logs crudos de las tools de la sesión.', 0, 'Verbose and unstructured.', 'Extensos y sin estructura.'),
       o('A sentiment score and frustration level so the human knows how upset the customer is before replying.', 'Una puntuación de sentimiento y nivel de frustración para que la persona sepa cuán molesto está el cliente antes de responder.', 0, 'Does not describe the case.', 'No describe el caso.')]),

    Q('s1q07', 1, '1.5', 'mid', 'deterministic',
      'Policy: refunds above $500 always require a human. Today the rule is in the system prompt and is violated about 2% of the time. What is the most reliable fix?',
      'Política: los reembolsos de más de 500 $ siempre requieren una persona. Hoy la regla está en el system prompt y se incumple en torno al 2 % de las veces. ¿Cuál es el arreglo más fiable?',
      [o('A PreToolUse hook on process_refund that denies amounts over $500 and points the agent to escalate_to_human.', 'Un hook PreToolUse en process_refund que rechace importes de más de 500 $ y dirija al agente a escalate_to_human.', 1, 'Interception guarantees the rule and redirects the workflow.', 'La intercepción garantiza la regla y redirige el flujo.'),
       o('A PostToolUse hook on process_refund that alerts a supervisor whenever a refund above $500 completes.', 'Un hook PostToolUse en process_refund que avise a un supervisor cada vez que se complete un reembolso de más de 500 $.', 0, 'Runs after the money moved.', 'Se ejecuta cuando el dinero ya se movió.'),
       o('Repeat the rule three times in the system prompt.', 'Repetir la regla tres veces en el system prompt.', 0, 'Still probabilistic.', 'Sigue siendo probabilístico.'),
       o('Have the model rate its confidence from 1 to 10 before each refund and block anything rated below 8.', 'Que el modelo puntúe su confianza del 1 al 10 antes de cada reembolso y bloquear todo lo que puntúe menos de 8.', 0, 'Self-confidence is poorly calibrated.', 'La autoconfianza está mal calibrada.')]),

    Q('s1q08', 1, '1.5', 'mid', 'deterministic',
      'get_customer returns created_at as a Unix timestamp, lookup_order as ISO 8601, and the returns system as "05/10/26". The agent sometimes tells customers they are outside the return window when they are not. Best fix?',
      'get_customer devuelve created_at como timestamp Unix, lookup_order como ISO 8601 y el sistema de devoluciones como «05/10/26». El agente a veces dice a los clientes que están fuera del plazo de devolución cuando no es así. ¿Mejor arreglo?',
      [o('A PostToolUse hook that normalizes all dates to ISO 8601 before the model processes them.', 'Un hook PostToolUse que normalice todas las fechas a ISO 8601 antes de que el modelo las procese.', 1, 'Deterministic normalization removes the ambiguity.', 'La normalización determinista elimina la ambigüedad.'),
       o('Add detailed date-conversion instructions and a format table to the system prompt for every source system.', 'Añadir instrucciones detalladas de conversión de fechas y una tabla de formatos al system prompt para cada sistema.', 0, 'Probabilistic and error-prone.', 'Probabilístico y propenso a errores.'),
       o('Ask customers for their delivery date instead.', 'Pedir a los clientes su fecha de entrega.', 0, 'Unreliable and shifts work to the customer.', 'Poco fiable y traslada el trabajo al cliente.'),
       o('Switch to a larger model that is better at interpreting mixed date formats from different systems.', 'Cambiar a un modelo más grande que interprete mejor formatos de fecha mezclados de distintos sistemas.', 0, 'Format inconsistency is not a capability problem.', 'La inconsistencia de formatos no es un problema de capacidad.')]),

    Q('s1q09', 1, '1.5', 'hard', 'structurederr',
      'Your PreToolUse hook denies refunds over $500, but the agent keeps calling process_refund with slightly lower amounts ($499) to "get it through". What change best fixes this?',
      'Tu hook PreToolUse rechaza los reembolsos de más de 500 $, pero el agente sigue llamando a process_refund con importes algo menores (499 $) para «colarlo». ¿Qué cambio lo arregla mejor?',
      [o('Return a deny reason that states the policy and explicitly directs the agent to escalate_to_human with a case summary.', 'Devolver un motivo de rechazo que explique la política y dirija explícitamente al agente a escalate_to_human con un resumen del caso.', 1, 'The deny reason is fed back to the model; give it the alternative path.', 'El motivo del rechazo vuelve al modelo; dale el camino alternativo.'),
       o('Lower the hook threshold to $400 so that amounts just under the limit are also blocked by the same rule.', 'Bajar el umbral del hook a 400 $ para que la misma regla bloquee también los importes justo por debajo del límite.', 0, 'The model will just split again.', 'El modelo simplemente volverá a dividir el importe.'),
       o('Remove process_refund from the agent.', 'Quitar process_refund al agente.', 0, 'Breaks valid small refunds.', 'Rompe los reembolsos pequeños válidos.'),
       o('Raise the temperature so the agent explores other strategies instead of repeating the same refund call.', 'Subir la temperatura para que el agente explore otras estrategias en lugar de repetir la misma llamada de reembolso.', 0, 'Irrelevant and risky.', 'Irrelevante y arriesgado.')]),

    Q('s1q10', 1, '1.1', 'mid', 'proportionate',
      'A product manager proposes replacing the agent with a hard-coded sequence: always get_customer → lookup_order → process_refund. What is the best response?',
      'Un product manager propone sustituir al agente por una secuencia fija: siempre get_customer → lookup_order → process_refund. ¿Cuál es la mejor respuesta?',
      [o('Keep the model-driven loop for flexibility, and enforce only the critical prerequisite (verified customer before refunds) programmatically.', 'Mantener el bucle dirigido por el modelo para tener flexibilidad, e imponer por código solo el prerrequisito crítico (cliente verificado antes de reembolsar).', 1, 'Model-driven decisions for the variable parts; deterministic gates where required.', 'Decisiones del modelo para la parte variable; compuertas deterministas donde hacen falta.'),
       o('Adopt the fixed sequence for every request type, because a predictable order is easier to audit and test.', 'Adoptar la secuencia fija para todo tipo de peticiones, porque un orden predecible es más fácil de auditar y probar.', 0, 'Breaks account issues, billing disputes and other paths.', 'Rompe los problemas de cuenta, las disputas de facturación y otros caminos.'),
       o('Remove all ordering constraints so the model is fully free.', 'Quitar todas las restricciones de orden para que el modelo sea totalmente libre.', 0, 'Loses the guarantee on identity verification.', 'Se pierde la garantía de verificación de identidad.'),
       o('Put a decision-tree classifier in front of the agent that picks one of several predefined, fixed tool sequences for each incoming request.', 'Poner delante del agente un clasificador de árbol de decisión que elija una de varias secuencias fijas y predefinidas de tools para cada petición.', 0, 'Over-engineered and rigid.', 'Sobrediseñado y rígido.')]),

    Q('s1q11', 1, '1.4', 'mid', 'deterministic',
      'Which TWO mechanisms provide deterministic (not probabilistic) guarantees that a refund is never issued before identity verification?',
      '¿Qué DOS mecanismos dan garantías deterministas (no probabilísticas) de que nunca se emite un reembolso antes de verificar la identidad?',
      [o('A programmatic prerequisite gate in the tool layer.', 'Una compuerta de prerrequisito programática en la capa de tools.', 1, 'Code-level enforcement.', 'Enforcement a nivel de código.'),
       o('A PreToolUse hook that denies process_refund without a verified ID.', 'Un hook PreToolUse que rechace process_refund sin un ID verificado.', 1, 'Interception before execution.', 'Intercepción antes de la ejecución.'),
       o('A system prompt instruction marked as CRITICAL.', 'Una instrucción del system prompt marcada como CRITICAL.', 0, 'Probabilistic.', 'Probabilística.'),
       o('Few-shot examples of correct ordering.', 'Ejemplos few-shot del orden correcto.', 0, 'Probabilistic.', 'Probabilísticos.'),
       o('Setting temperature to 0.', 'Poner la temperatura a 0.', 0, 'Does not guarantee ordering.', 'No garantiza el orden.')]),

    Q('s1q12', 1, '1.7', 'mid', 'rootcause',
      'A customer returns the next day to the same chat. Overnight, their order moved from "processing" to "shipped". Resuming yesterday\'s session, the agent tells them it can still cancel the order. What is the better approach?',
      'Un cliente vuelve al día siguiente al mismo chat. Durante la noche, su pedido pasó de «processing» a «shipped». Al reanudar la sesión de ayer, el agente le dice que aún puede cancelar el pedido. ¿Cuál es el mejor enfoque?',
      [o('Start a fresh session seeded with a structured case summary and re-query current order state, rather than trusting stale tool results.', 'Empezar una sesión nueva con un resumen estructurado del caso y volver a consultar el estado actual del pedido, en lugar de fiarse de resultados obsoletos.', 1, 'Stale results mislead; inject accurate state.', 'Los resultados obsoletos engañan; inyecta el estado real.'),
       o('Resume yesterday\'s session as is and add an instruction telling the agent to double-check every order\'s status carefully before acting.', 'Reanudar la sesión de ayer tal cual y añadir una instrucción para que el agente revise con cuidado el estado de cada pedido antes de actuar.', 0, 'It will still trust the old tool result.', 'Seguirá confiando en el resultado viejo.'),
       o('Fork yesterday\'s session so the agent keeps the full history but continues on a separate, clean branch.', 'Hacer fork de la sesión de ayer para que el agente conserve todo el historial pero continúe en una rama separada y limpia.', 0, 'A fork inherits the same stale data.', 'Un fork hereda los mismos datos obsoletos.'),
       o('Increase max_tokens.', 'Aumentar max_tokens.', 0, 'Unrelated.', 'No tiene relación.')]),

    Q('s1q13', 1, '1.1', 'basic', 'documented',
      'What role should a maximum-turns limit play in the support agent\'s loop?',
      '¿Qué papel debe tener un límite máximo de turnos en el bucle del agente de soporte?',
      [o('A safety net against runaway loops; normal termination still relies on stop_reason.', 'Una red de seguridad contra bucles desbocados; la terminación normal sigue dependiendo de stop_reason.', 1, 'Correct use of iteration caps.', 'Uso correcto de un tope de iteraciones.'),
       o('The primary way to decide that the task is complete, since it keeps cost and latency predictable.', 'La forma principal de decidir que la tarea terminó, ya que mantiene predecibles el costo y la latencia.', 0, 'Explicit anti-pattern.', 'Anti-patrón explícito.'),
       o('None; limits should never exist.', 'Ninguno; los límites nunca deberían existir.', 0, 'A safety net is still prudent.', 'Una red de seguridad sigue siendo prudente.'),
       o('A trigger that forces escalation to a human once the conversation passes three turns.', 'Un disparador que fuerza el escalado a una persona cuando la conversación supera los tres turnos.', 0, 'Turn count is not an escalation criterion.', 'El número de turnos no es un criterio de escalado.')]),

    Q('s1q14', 1, '1.6', 'hard', 'proportionate',
      'Billing disputes have very different root causes (duplicate capture, currency conversion, promo misapplied, fraud). How should the agent decompose its investigation?',
      'Las disputas de facturación tienen causas muy distintas (cobro duplicado, conversión de moneda, promoción mal aplicada, fraude). ¿Cómo debe descomponer el agente su investigación?',
      [o('Adaptively: generate the next checks based on what each lookup reveals.', 'De forma adaptativa: generar las siguientes comprobaciones según lo que revela cada consulta.', 1, 'Open-ended investigation suits dynamic decomposition.', 'Una investigación abierta encaja con la descomposición dinámica.'),
       o('A fixed chain that runs every available check for every dispute, in the same order each time.', 'Una cadena fija que ejecute todas las comprobaciones disponibles en cada disputa, siempre en el mismo orden.', 0, 'Wasteful and blind to findings.', 'Derrochadora y ciega a lo que se descubre.'),
       o('Escalate every dispute to a human.', 'Escalar todas las disputas a una persona.', 0, 'Hurts first-contact resolution.', 'Empeora la resolución en el primer contacto.'),
       o('Ask the customer which of the possible root causes applies before running any lookups.', 'Preguntar al cliente cuál de las posibles causas aplica antes de hacer ninguna consulta.', 0, 'Customers rarely know.', 'Los clientes rara vez lo saben.')]),

    /* ---------------- D2 ---------------- */
    Q('s1q15', 2, '2.1', 'basic', 'proportionate',
      'Production logs show the agent frequently calls get_customer when users ask about orders (e.g., "check my order #12345"), instead of calling lookup_order. Both tools have minimal descriptions ("Retrieves customer information" / "Retrieves order details") and accept similar identifier formats. What\'s the most effective first step to improve tool selection reliability?',
      'Los logs de producción muestran que el agente llama a menudo a get_customer cuando los usuarios preguntan por pedidos (p. ej. «check my order #12345»), en lugar de llamar a lookup_order. Ambas tools tienen descripciones mínimas («Retrieves customer information» / «Retrieves order details») y aceptan formatos de identificador parecidos. ¿Cuál es el primer paso más eficaz para mejorar la fiabilidad de la selección de tools?',
      [o('Add few-shot examples to the system prompt demonstrating correct tool selection patterns, with 5-8 examples showing order-related queries routing to lookup_order.', 'Añadir ejemplos few-shot al system prompt que muestren la selección correcta, con 5-8 ejemplos de consultas sobre pedidos que van a lookup_order.', 0,
         'Adds token overhead without fixing the underlying issue.', 'Añade tokens sin arreglar el problema de fondo.'),
       o('Expand each tool\'s description to include input formats it handles, example queries, edge cases, and boundaries explaining when to use it versus similar tools.', 'Ampliar la descripción de cada tool con los formatos de entrada que maneja, consultas de ejemplo, casos límite y fronteras que expliquen cuándo usarla frente a tools parecidas.', 1,
         'Descriptions are the primary selection mechanism; low-effort, high-leverage fix of the root cause.', 'Las descripciones son el mecanismo principal de selección; arreglo de la causa raíz con poco esfuerzo y mucho impacto.'),
       o('Implement a routing layer that parses user input before each turn and pre-selects the appropriate tool based on detected keywords and identifier patterns.', 'Implementar una capa de enrutado que analice la entrada antes de cada turno y preseleccione la tool según palabras clave y patrones de identificador.', 0,
         'Over-engineered; bypasses the LLM\'s language understanding.', 'Sobrediseñado; se salta la comprensión del lenguaje del modelo.'),
       o('Consolidate both tools into a single lookup_entity tool that accepts any identifier and internally determines which backend to query.', 'Consolidar ambas tools en una sola lookup_entity que acepte cualquier identificador y decida internamente qué backend consultar.', 0,
         'Valid architecture, but more effort than a first step warrants.', 'Arquitectura válida, pero cuesta más de lo que justifica un primer paso.')],
      { official: true }),

    Q('s1q16', 2, '2.2', 'basic', 'structurederr',
      'process_refund returns isError: true with the text "Operation failed" both for gateway timeouts and for orders outside the refund window. The agent retries both cases repeatedly. Best fix?',
      'process_refund devuelve isError: true con el texto «Operation failed» tanto para timeouts de la pasarela como para pedidos fuera del plazo de reembolso. El agente reintenta ambos casos una y otra vez. ¿Mejor arreglo?',
      [o('Return structured metadata: errorCategory (transient vs business), isRetryable, and a human-readable explanation.', 'Devolver metadatos estructurados: errorCategory (transitorio vs negocio), isRetryable y una explicación legible.', 1, 'Lets the agent retry transient errors and explain business ones.', 'Permite al agente reintentar los errores transitorios y explicar los de negocio.'),
       o('Limit retries to one attempt for every error so neither timeouts nor policy errors loop for long.', 'Limitar a un reintento todos los errores para que ni los timeouts ni los errores de política se repitan mucho.', 0, 'Treats different errors the same.', 'Trata igual errores distintos.'),
       o('Return isError: false with an explanatory message for policy violations, so the agent stops retrying them.', 'Devolver isError: false con un mensaje explicativo para las violaciones de política, para que el agente deje de reintentarlas.', 0, 'Disguises a failure as success.', 'Disfraza un fallo de éxito.'),
       o('Log the errors and say nothing to the agent.', 'Registrar los errores y no decirle nada al agente.', 0, 'The agent cannot recover without information.', 'El agente no puede recuperarse sin información.')]),

    Q('s1q17', 2, '2.2', 'mid', 'structurederr',
      'For new customers with no orders, lookup_orders_by_email returns an error, and the agent tells them "our system is temporarily unavailable". What is the correct design?',
      'Para clientes nuevos sin pedidos, lookup_orders_by_email devuelve un error, y el agente les dice «nuestro sistema no está disponible temporalmente». ¿Cuál es el diseño correcto?',
      [o('Return a successful result with an empty list; reserve errors for real access failures like timeouts.', 'Devolver un resultado exitoso con la lista vacía; reservar los errores para fallos de acceso reales, como timeouts.', 1, 'A valid empty result is not an error.', 'Un resultado vacío válido no es un error.'),
       o('Return a transient error marked retryable, so the agent tries again in case the order index is still updating.', 'Devolver un error transitorio marcado como reintentable, por si el índice de pedidos aún se está actualizando.', 0, 'Causes pointless retries.', 'Provoca reintentos sin sentido.'),
       o('Return a permission error.', 'Devolver un error de permisos.', 0, 'Misleading category.', 'Categoría engañosa.'),
       o('Raise an exception so the agent stops and asks the customer to confirm their email address first.', 'Lanzar una excepción para que el agente se detenga y pida al cliente que confirme primero su email.', 0, 'Ends a normal flow.', 'Termina un flujo normal.')]),

    Q('s1q18', 2, '2.3', 'mid', 'leastprivilege',
      'The support agent now has 18 tools (CRM, orders, refunds, inventory, marketing, analytics…). Tool-selection errors have doubled. What is the best direction?',
      'El agente de soporte tiene ahora 18 tools (CRM, pedidos, reembolsos, inventario, marketing, analítica…). Los errores de selección de tools se han duplicado. ¿Cuál es la mejor dirección?',
      [o('Restrict the agent to the 4–5 tools its role needs; move unrelated capabilities elsewhere.', 'Restringir el agente a las 4–5 tools que su rol necesita; llevar las capacidades no relacionadas a otro lugar.', 1, 'Too many tools increase decision complexity.', 'Demasiadas tools aumentan la complejidad de decisión.'),
       o('Add a system prompt section that lists all 18 tools ranked by importance with one example each.', 'Añadir una sección al system prompt que liste las 18 tools ordenadas por importancia, con un ejemplo de cada una.', 0, 'Still 18 choices.', 'Siguen siendo 18 opciones.'),
       o('Use a model with a larger context window so all 18 tool definitions fit comfortably in every request.', 'Usar un modelo con una ventana de contexto mayor para que las 18 definiciones de tools quepan holgadas en cada petición.', 0, 'Context size is not the issue.', 'El tamaño del contexto no es el problema.'),
       o('Set tool_choice to "any".', 'Poner tool_choice en "any".', 0, 'Forces a call but does not improve which one.', 'Obliga a llamar a una tool, pero no mejora cuál.')]),

    Q('s1q19', 2, '2.3', 'hard', 'documented',
      'You want the very first action of every conversation to be get_customer, after which the agent decides freely. Which configuration fits?',
      'Quieres que la primera acción de cada conversación sea get_customer y que después el agente decida libremente. ¿Qué configuración encaja?',
      [o('Force tool_choice {"type": "tool", "name": "get_customer"} on the first request, then use "auto" in follow-up turns.', 'Forzar tool_choice {"type": "tool", "name": "get_customer"} en la primera petición y usar "auto" en los turnos siguientes.', 1, 'Forced selection for the first step, model-driven afterwards.', 'Selección forzada para el primer paso y decisión del modelo después.'),
       o('Set tool_choice to "any" for every turn so the model is always required to call one of its tools.', 'Poner tool_choice en "any" en todos los turnos para que el modelo siempre esté obligado a llamar a una de sus tools.', 0, 'Forces some tool every turn, not get_customer.', 'Obliga a llamar a alguna tool en cada turno, no a get_customer.'),
       o('tool_choice "auto" plus a prompt instruction.', 'tool_choice "auto" más una instrucción en el prompt.', 0, 'Probabilistic.', 'Probabilístico.'),
       o('Remove all other tools from the request until get_customer has run, then add them back for later turns.', 'Quitar todas las demás tools de la petición hasta que se ejecute get_customer y volver a añadirlas en los turnos siguientes.', 0, 'Clumsy; forced tool_choice does this cleanly.', 'Torpe; tool_choice forzado lo hace de forma limpia.')]),

    Q('s1q20', 2, '2.4', 'mid', 'documented',
      'The agent makes several exploratory calls per conversation just to find which policy documents exist (returns, warranty, shipping). How can the MCP server reduce this?',
      'El agente hace varias llamadas exploratorias por conversación solo para saber qué documentos de política existen (devoluciones, garantía, envíos). ¿Cómo puede reducir esto el servidor MCP?',
      [o('Expose the policy catalog as MCP resources so the agent sees what is available without exploratory tool calls.', 'Exponer el catálogo de políticas como recursos MCP para que el agente vea lo disponible sin llamadas exploratorias.', 1, 'Resources expose content catalogs.', 'Los recursos exponen catálogos de contenido.'),
       o('Add a list_all_documents tool that the agent calls at the start of each conversation to see what exists.', 'Añadir una tool list_all_documents que el agente llame al inicio de cada conversación para ver qué existe.', 0, 'Still a tool call per conversation.', 'Sigue siendo una llamada a tool por conversación.'),
       o('Paste the full text of every policy into the system prompt so the agent never has to look them up.', 'Pegar el texto completo de todas las políticas en el system prompt para que el agente nunca tenga que buscarlas.', 0, 'Bloats every request.', 'Infla todas las peticiones.'),
       o('Increase the agent\'s max_tokens.', 'Aumentar max_tokens del agente.', 0, 'Unrelated.', 'No tiene relación.')]),

    Q('s1q21', 2, '2.4', 'basic', 'documented',
      'Your team needs a shared Zendesk MCP server for everyone working on the support agent repo, without committing the API token. Where and how do you configure it?',
      'Tu equipo necesita un servidor MCP de Zendesk compartido para todos los que trabajan en el repo del agente de soporte, sin versionar el token de la API. ¿Dónde y cómo lo configuras?',
      [o('In the project .mcp.json, with "${ZENDESK_TOKEN}" environment variable expansion.', 'En el .mcp.json del proyecto, con expansión de variable de entorno "${ZENDESK_TOKEN}".', 1, 'Project scope + env expansion.', 'Alcance de proyecto + expansión de variables.'),
       o('In each developer\'s ~/.claude.json, with the token written inline so nothing secret is committed.', 'En el ~/.claude.json de cada desarrollador, con el token escrito directamente para no versionar nada secreto.', 0, 'Not shared via version control.', 'No se comparte por control de versiones.'),
       o('In CLAUDE.md under a "Servers" heading.', 'En CLAUDE.md bajo un título «Servers».', 0, 'CLAUDE.md does not configure MCP.', 'CLAUDE.md no configura MCP.'),
       o('In the project .mcp.json with the token inline, since the repository is private to the team anyway.', 'En el .mcp.json del proyecto con el token escrito, ya que de todos modos el repositorio es privado del equipo.', 0, 'Leaks a secret.', 'Filtra un secreto.')]),

    Q('s1q22', 2, '2.1', 'mid', 'rootcause',
      'The agent issues store credit when customers clearly asked for a refund to their card. process_refund and issue_store_credit both say "Compensates the customer for an order." What should you change first?',
      'El agente emite crédito en tienda cuando los clientes pidieron claramente un reembolso a su tarjeta. process_refund e issue_store_credit dicen ambas «Compensates the customer for an order.» ¿Qué deberías cambiar primero?',
      [o('Rewrite both descriptions to state what each does, when to use it, and when to use the other instead.', 'Reescribir ambas descripciones para decir qué hace cada una, cuándo usarla y cuándo usar la otra.', 1, 'Overlapping descriptions cause misrouting.', 'Las descripciones solapadas causan mal enrutado.'),
       o('Remove issue_store_credit.', 'Quitar issue_store_credit.', 0, 'Loses a legitimate capability.', 'Se pierde una capacidad legítima.'),
       o('Add a PostToolUse hook that converts store credit into a card refund whenever the customer asked for one.', 'Añadir un hook PostToolUse que convierta el crédito en tienda en un reembolso a la tarjeta cuando el cliente lo pidió.', 0, 'Patches the symptom.', 'Parchea el síntoma.'),
       o('Train a classifier on past tickets to choose the compensation type before the agent calls any tool.', 'Entrenar un clasificador con tickets pasados que elija el tipo de compensación antes de que el agente llame a ninguna tool.', 0, 'Over-engineered first step.', 'Primer paso sobrediseñado.')]),

    Q('s1q23', 2, '2.2', 'hard', 'structurederr',
      'Which TWO pieces of metadata in a tool error most help the agent choose between retrying, explaining to the customer, and escalating?',
      '¿Qué DOS metadatos de un error de tool ayudan más al agente a elegir entre reintentar, explicar al cliente o escalar?',
      [o('errorCategory (transient / validation / business / permission)', 'errorCategory (transitorio / validación / negocio / permiso)', 1, 'Tells the kind of failure.', 'Indica el tipo de fallo.'),
       o('isRetryable', 'isRetryable', 1, 'Prevents wasted retries.', 'Evita reintentos inútiles.'),
       o('The server\'s CPU usage at the time', 'El uso de CPU del servidor en ese momento', 0, 'Not actionable for the agent.', 'No sirve al agente para decidir.'),
       o('A random request ID only', 'Solo un ID de petición aleatorio', 0, 'Useful for logs, not decisions.', 'Útil para los logs, no para decidir.'),
       o('The full stack trace', 'El stack trace completo', 0, 'Verbose and not decision-oriented.', 'Extenso y no orientado a decidir.')]),

    /* ---------------- D5 ---------------- */
    Q('s1q24', 5, '5.2', 'mid', 'explicit',
      'Your agent achieves 55% first-contact resolution, well below the 80% target. Logs show it escalates straightforward cases (standard damage replacements with photo evidence) while attempting to autonomously handle complex situations requiring policy exceptions. What\'s the most effective way to improve escalation calibration?',
      'Tu agente logra un 55 % de resolución en el primer contacto, muy por debajo de la meta del 80 %. Los logs muestran que escala casos sencillos (reposiciones estándar por daño con foto) mientras intenta resolver solo situaciones complejas que requieren excepciones de política. ¿Cuál es la forma más eficaz de calibrar mejor el escalado?',
      [o('Add explicit escalation criteria to your system prompt with few-shot examples demonstrating when to escalate versus resolve autonomously.', 'Añadir criterios de escalado explícitos al system prompt con ejemplos few-shot que muestren cuándo escalar y cuándo resolver de forma autónoma.', 1,
         'Directly addresses unclear decision boundaries; proportionate first response.', 'Ataca directamente unos límites de decisión poco claros; es la primera respuesta proporcionada.'),
       o('Have the agent self-report a confidence score (1-10) before each response and automatically route requests to humans when confidence falls below a threshold.', 'Que el agente informe una puntuación de confianza (1-10) antes de cada respuesta y enrutar a personas cuando baje de un umbral.', 0,
         'Self-reported confidence is poorly calibrated; the agent is already confidently wrong.', 'La confianza autoinformada está mal calibrada; el agente ya se equivoca con seguridad.'),
       o('Deploy a separate classifier model trained on historical tickets to predict which requests need escalation before the main agent begins processing.', 'Desplegar un modelo clasificador entrenado con tickets históricos que prediga qué peticiones necesitan escalado antes de que empiece el agente.', 0,
         'Over-engineered; requires labeled data and ML infrastructure before trying prompts.', 'Sobrediseñado; requiere datos etiquetados e infraestructura de ML antes de probar con prompts.'),
       o('Implement sentiment analysis to detect customer frustration levels and automatically escalate when negative sentiment exceeds a threshold.', 'Implementar análisis de sentimiento para detectar la frustración y escalar automáticamente cuando supere un umbral.', 0,
         'Sentiment does not correlate with case complexity.', 'El sentimiento no se correlaciona con la complejidad del caso.')],
      { official: true }),

    Q('s1q25', 5, '5.2', 'basic', 'documented',
      'A customer\'s first message is: "I want to speak to a human, not a bot." The issue appears to be a simple address change. What should the agent do?',
      'El primer mensaje de un cliente es: «Quiero hablar con una persona, no con un bot.» El problema parece un simple cambio de dirección. ¿Qué debe hacer el agente?',
      [o('Escalate to a human immediately, without investigating first.', 'Escalar a una persona de inmediato, sin investigar antes.', 1, 'Explicit requests are honored immediately.', 'Las peticiones explícitas se atienden de inmediato.'),
       o('Quickly change the address first since it is simple, then offer to transfer to a human.', 'Cambiar primero la dirección, ya que es sencillo, y luego ofrecer pasar con una persona.', 0, 'Ignores the explicit request.', 'Ignora la petición explícita.'),
       o('Explain politely that the bot can resolve address changes faster than a human.', 'Explicar con educación que el bot puede resolver los cambios de dirección más rápido que una persona.', 0, 'Argues with the customer.', 'Discute con el cliente.'),
       o('Run sentiment analysis first.', 'Hacer primero un análisis de sentimiento.', 0, 'The request is already explicit.', 'La petición ya es explícita.')]),

    Q('s1q26', 5, '5.2', 'basic', 'documented',
      'get_customer("Carlos Ruiz") returns four matching accounts. What should the agent do?',
      'get_customer("Carlos Ruiz") devuelve cuatro cuentas que coinciden. ¿Qué debe hacer el agente?',
      [o('Ask the customer for an additional identifier (email, phone, or order number).', 'Pedir al cliente un identificador adicional (email, teléfono o número de pedido).', 1, 'Clarify rather than guess.', 'Aclara en lugar de adivinar.'),
       o('Pick the account with the most recent order, since it is most likely the one contacting you.', 'Elegir la cuenta con el pedido más reciente, ya que es la que con más probabilidad está escribiendo.', 0, 'Heuristic selection risks the wrong account.', 'Elegir por heurística arriesga la cuenta equivocada.'),
       o('Escalate to a human immediately.', 'Escalar a una persona de inmediato.', 0, 'Resolvable with one question.', 'Se resuelve con una pregunta.'),
       o('Show the customer the four accounts with partial details and let them choose theirs.', 'Mostrar al cliente las cuatro cuentas con datos parciales y dejar que elija la suya.', 0, 'Exposes other customers\' data.', 'Expone datos de otros clientes.')]),

    Q('s1q27', 5, '5.2', 'mid', 'rootcause',
      'A customer asks the agent to match a lower price they found at a competitor. Your policy covers price adjustments only for drops on your own site. What should the agent do?',
      'Un cliente pide al agente que iguale un precio más bajo que encontró en la competencia. Tu política solo cubre ajustes de precio por bajadas en tu propia web. ¿Qué debe hacer el agente?',
      [o('Escalate: the policy is silent on competitor price matching, which is a policy gap.', 'Escalar: la política no dice nada sobre igualar precios de la competencia, es un vacío en la política.', 1, 'Policy gaps are an escalation trigger.', 'Los vacíos en la política son motivo de escalado.'),
       o('Approve the price match, because the policy does not explicitly forbid competitor matching.', 'Aprobar la igualación de precio, porque la política no prohíbe explícitamente igualar a la competencia.', 0, 'Silence is not permission.', 'Que no lo diga no es permiso.'),
       o('Deny the request, because the policy only covers price drops on your own website.', 'Rechazar la petición, porque la política solo cubre bajadas de precio en tu propia web.', 0, 'Treats silence as prohibition; a human should decide.', 'Toma el silencio como prohibición; debe decidir una persona.'),
       o('Offer a 50% compromise.', 'Ofrecer un término medio del 50 %.', 0, 'Invents policy.', 'Inventa política.')]),

    Q('s1q28', 5, '5.2', 'mid', 'badproxy',
      'A customer writes angrily: "This is the THIRD time the item arrived broken!!" The case is a standard replacement fully covered by policy. Best behavior?',
      'Un cliente escribe enfadado: «¡¡Es la TERCERA vez que el producto llega roto!!» El caso es una reposición estándar totalmente cubierta por la política. ¿Mejor comportamiento?',
      [o('Acknowledge the frustration and offer the replacement; escalate only if the customer reiterates wanting a human.', 'Reconocer la frustración y ofrecer la reposición; escalar solo si el cliente insiste en querer una persona.', 1, 'Frustration alone is not an escalation trigger.', 'La frustración por sí sola no es motivo de escalado.'),
       o('Escalate to a human, because strongly negative sentiment signals a case the agent should not handle.', 'Escalar a una persona, porque un sentimiento muy negativo indica un caso que el agente no debe manejar.', 0, 'Sentiment does not measure complexity.', 'El sentimiento no mide la complejidad.'),
       o('Ignore the emotion and process silently.', 'Ignorar la emoción y procesar en silencio.', 0, 'Poor experience; acknowledge it.', 'Mala experiencia; hay que reconocerla.'),
       o('Offer a full refund instead of a replacement, since a third failure justifies going beyond the request.', 'Ofrecer un reembolso completo en lugar de la reposición, ya que un tercer fallo justifica ir más allá de lo pedido.', 0, 'Not what the customer asked.', 'No es lo que pidió el cliente.')]),

    Q('s1q29', 5, '5.1', 'mid', 'rootcause',
      'In sessions longer than 30 turns, the agent forgets that it promised a refund of $86.40 by Friday. The history is progressively summarized. What is the most reliable fix?',
      'En sesiones de más de 30 turnos, el agente olvida que prometió un reembolso de 86,40 $ para el viernes. El historial se resume de forma progresiva. ¿Cuál es el arreglo más fiable?',
      [o('Keep a persistent case-facts block (amounts, dates, order IDs, promises) included in every prompt outside the summary.', 'Mantener un bloque persistente de case facts (importes, fechas, IDs de pedido, promesas) incluido en cada prompt, fuera del resumen.', 1, 'Facts survive summarization verbatim.', 'Los datos sobreviven literalmente al resumen.'),
       o('Summarize less often, for example every 60 turns instead of every 20, so that fewer amounts and dates get compressed away.', 'Resumir con menos frecuencia, por ejemplo cada 60 turnos en lugar de cada 20, para que se compriman menos importes y fechas.', 0, 'Delays the loss; does not prevent it.', 'Retrasa la pérdida, pero no la evita.'),
       o('Switch to a model with a larger context window.', 'Cambiar a un modelo con más contexto.', 0, 'Summaries still lose details.', 'Los resúmenes siguen perdiendo detalles.'),
       o('Ask the customer to restate key details such as amounts and dates every 10 turns.', 'Pedir al cliente que repita los datos clave, como importes y fechas, cada 10 turnos.', 0, 'Bad experience.', 'Mala experiencia.')]),

    Q('s1q30', 5, '5.1', 'basic', 'proportionate',
      'Each lookup_order call returns 45 fields, but return cases only use 5 (status, delivery date, items, total, return eligibility). Context fills quickly in long sessions. Best fix?',
      'Cada llamada a lookup_order devuelve 45 campos, pero los casos de devolución solo usan 5 (estado, fecha de entrega, artículos, total, elegibilidad para devolución). El contexto se llena rápido en sesiones largas. ¿Mejor arreglo?',
      [o('Trim tool output to the relevant fields before it accumulates in context.', 'Recortar la salida de la tool a los campos relevantes antes de que se acumule en el contexto.', 1, 'Tool results consume tokens out of proportion to their relevance.', 'Los resultados de tools consumen tokens en desproporción con su relevancia.'),
       o('Call lookup_order less often and rely on what the customer says about the order.', 'Llamar menos a lookup_order y fiarse de lo que dice el cliente sobre el pedido.', 0, 'The agent needs the data.', 'El agente necesita el dato.'),
       o('Use the Batches API for lookups.', 'Usar la Batches API para las consultas.', 0, 'Wrong tool; latency.', 'Herramienta equivocada; añade latencia.'),
       o('Summarize every tool result with an extra model call before adding it to the history.', 'Resumir cada resultado de tool con una llamada extra al modelo antes de añadirlo al historial.', 0, 'Costly and lossy; trimming is simpler.', 'Costoso y con pérdidas; recortar es más simple.')]),

    Q('s1q31', 5, '5.1', 'hard', 'rootcause',
      'You inject a 20-page returns policy into the context. The agent applies rules from the first and last pages well but often misses a key exception on page 11. What helps most?',
      'Inyectas en el contexto una política de devoluciones de 20 páginas. El agente aplica bien las reglas de la primera y la última página, pero a menudo pasa por alto una excepción clave de la página 11. ¿Qué ayuda más?',
      [o('Put a summary of key rules and exceptions at the beginning and organize the rest with explicit section headers.', 'Poner al principio un resumen de las reglas y excepciones clave y organizar el resto con encabezados explícitos.', 1, 'Mitigates the "lost in the middle" effect.', 'Mitiga el efecto «lost in the middle».'),
       o('Include the full policy twice in the context so the exception on page 11 appears more often.', 'Incluir la política completa dos veces en el contexto para que la excepción de la página 11 aparezca más.', 0, 'Doubles tokens; does not fix position effects.', 'Duplica tokens; no arregla los efectos de posición.'),
       o('Switch to a larger model with a longer context window that can attend to all 20 pages of the policy with equal care.', 'Cambiar a un modelo más grande con una ventana de contexto mayor que atienda con el mismo cuidado las 20 páginas de la política.', 0, 'Position effects persist.', 'Los efectos de posición persisten.'),
       o('Move page 11 to the end only.', 'Mover solo la página 11 al final.', 0, 'Fragile; other middle content will be missed.', 'Frágil; se perderá otro contenido del medio.')]),

    Q('s1q32', 5, '5.5', 'hard', 'rootcause',
      'Overall first-contact resolution is 82%, above target, so leadership wants to reduce human QA. A breakdown shows billing disputes at 41%. What should you recommend?',
      'La resolución global en el primer contacto es del 82 %, por encima de la meta, así que la dirección quiere reducir el control de calidad humano. Un desglose muestra las disputas de facturación en un 41 %. ¿Qué deberías recomendar?',
      [o('Validate performance by case type before reducing review; keep human review where a segment underperforms.', 'Validar el rendimiento por tipo de caso antes de reducir la revisión; mantener la revisión humana donde un segmento rinde mal.', 1, 'Aggregate metrics can mask weak segments.', 'Las métricas agregadas pueden ocultar segmentos débiles.'),
       o('Reduce human QA across all case types, since 82% overall already beats the 80% target.', 'Reducir el control humano en todos los tipos de caso, ya que el 82 % global ya supera la meta del 80 %.', 0, 'Ignores the 41% segment.', 'Ignora el segmento del 41 %.'),
       o('Escalate every conversation to a human.', 'Escalar todas las conversaciones a una persona.', 0, 'Disproportionate.', 'Desproporcionado.'),
       o('Raise the agent\'s self-reported confidence threshold so it escalates more of the uncertain disputes.', 'Subir el umbral de confianza autoinformada del agente para que escale más disputas inciertas.', 0, 'Unreliable proxy.', 'Proxy poco fiable.')])
  ]);
})();
